import 'package:flutter_bloc/flutter_bloc.dart';

// Cubit: 상태는 정수(int)입니다.
class CounterCubit extends Cubit<int> {
  CounterCubit() : super(0);

  void increment() => emit(state + 1);
  void decrement() => emit(state - 1);
}

import 'package:bloc_test/bloc_test.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:my_app/counter/counter_cubit.dart';

void main() {
  group('CounterCubit Test', () {
    // 1. 초기 상태 테스트
    blocTest<CounterCubit, int>(
      '초기 상태는 0이어야 한다.',
      build: () => CounterCubit(),
      // act: 아무것도 호출하지 않음
      expect: () => const <int>[], // act가 없으면 상태 변화도 없어야 함
    );

    // 2. increment 호출 시 상태 변화 테스트
    blocTest<CounterCubit, int>(
      'increment 호출 시 [1]을 방출해야 한다.',
      build: () => CounterCubit(),
      act: (cubit) => cubit.increment(),
      expect: () => const <int>[1], // 0 -> 1로 변화
    );

    // 3. 여러 번의 호출 및 복합 상태 변화 테스트
    blocTest<CounterCubit, int>(
      'increment와 decrement 호출 시 [1, 0]을 방출해야 한다.',
      build: () => CounterCubit(),
      act: (cubit) {
        cubit.increment();
        cubit.decrement();
      },
      expect: () => const <int>[1, 0],
    );
  });
}

// lib/counter/counter_bloc.dart (BLoC 정의)
abstract class CounterEvent {}
class CounterIncrementPressed extends CounterEvent {}

class CounterBloc extends Bloc<CounterEvent, int> {
  CounterBloc() : super(0) {
    on<CounterIncrementPressed>((event, emit) => emit(state + 1));
  }
}

// test/counter_bloc_test.dart (테스트 코드)
void main() {
  group('CounterBloc Test', () {
    blocTest<CounterBloc, int>(
      'CounterIncrementPressed 이벤트 시 [1]을 방출해야 한다.',
      build: () => CounterBloc(),
      act: (bloc) => bloc.add(CounterIncrementPressed()),
      expect: () => const <int>[1],
    );

    blocTest<CounterBloc, int>(
      '여러 이벤트 시 [1, 2]를 방출해야 한다.',
      build: () => CounterBloc(),
      act: (bloc) {
        bloc.add(CounterIncrementPressed());
        bloc.add(CounterIncrementPressed());
      },
      expect: () => const <int>[1, 2],
    );
  });
}

import 'package:bloc_test/bloc_test.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:my_app/counter/counter_cubit.dart';

// 1. Mock Cubit 정의 (bloc_test 제공)
class MockCounterCubit extends MockCubit<int> implements CounterCubit {}

void main() {
  group('whenListen Test', () {
    test('MockCubit의 스트림 출력을 Stubbing한다.', () {
      // Mock 인스턴스 생성
      final cubit = MockCounterCubit();

      // whenListen: cubit의 stream이 [10, 20, 30]을 방출하도록 설정
      whenListen(cubit, Stream.fromIterable([10, 20, 30]));

      // 검증: cubit.stream이 설정된 값들을 순서대로 방출하는지 확인
      expectLater(cubit.stream, emitsInOrder(<int>[10, 20, 30]));
    });

    test('MockBloc의 초기 상태를 Stubbing한다.', () {
      final cubit = MockCounterCubit();
      // Mock의 현재 상태(state)를 99로 설정
      when(cubit.state).thenReturn(99);

      expect(cubit.state, 99);
    });
  });
}
